using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
using System.Windows.Input;
using System.Windows.Media.Imaging;
using System.Reflection;
using System.Windows.Controls.Primitives;
namespace Dafeiyu.Tests
{
    public static class PermissionUiSmoke
    {
        static int checks;static readonly BindingFlags hidden=BindingFlags.NonPublic|BindingFlags.Instance;
        static void Check(bool ok,string reason){if(!ok)throw new Exception(reason);checks++;}
        static void Pump(){Dispatcher.CurrentDispatcher.Invoke(DispatcherPriority.Background,new Action(delegate{}));}
        static void Click(Button button){button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
        static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,hidden).GetValue(o);}
        static void WithConfirmation(Action change,bool accept,Action<Window> inspect=null){bool shown=false;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(25)};timer.Tick+=delegate{var dialog=Application.Current.Windows.OfType<Window>().FirstOrDefault(w=>w.Name=="PermissionChangeDialog"&&w.IsVisible);if(dialog==null)return;timer.Stop();shown=true;if(inspect!=null)inspect(dialog);Click(All<Button>(dialog).Single(b=>b.Name==(accept?"ConfirmPermissionChange":"CancelPermissionChange")));};timer.Start();try{change();}finally{timer.Stop();}Check(shown,"permission change presents an application-owned confirmation");}
        static void Capture(FrameworkElement element,string name){element.UpdateLayout();var bitmap=new RenderTargetBitmap((int)Math.Ceiling(element.ActualWidth),(int)Math.Ceiling(element.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(element);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(Directory.GetCurrentDirectory(),"work","permissions",name+".png")))png.Save(file);}
        static IEnumerable<T> All<T>(DependencyObject p) where T:DependencyObject{if(p is T)yield return (T)p;for(int i=0;i<VisualTreeHelper.GetChildrenCount(p);i++)foreach(var item in All<T>(VisualTreeHelper.GetChild(p,i)))yield return item;}
        [STAThread] public static int Main(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};PetWindow pet=null;try{
            string root=Path.Combine(Directory.GetCurrentDirectory(),"work","permissions","ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var cfg=new PetSettings{AutoUpdate=false,GreetingEnabled=false,SaveChatHistory=false,AgentWorkspace=root,OnboardingState="completed",ShowPredictedMessages=false};foreach(var key in cfg.Hotkeys.Keys.ToArray())cfg.Hotkeys[key]="";
            pet=new PetWindow(null,cfg,new SettingsStore(Path.Combine(root,"settings.json")),null);var panel=new WorkSettingsPanel(pet);var owner=new Window{Content=panel,Width=900,Height=850};owner.Show();owner.UpdateLayout();
            var approval=All<ComboBox>(panel).Single(c=>c.Name=="AgentApprovalMode");Check(approval.Items.Cast<string>().SequenceEqual(new[]{"请求批准","帮我批准","完全访问权限"})&&approval.SelectedIndex==1&&!panel.HasUnsavedChanges,"new settings show exactly three profiles with automatic review selected");
            cfg.AgentApprovalMode=AgentApprovalMode.Legacy;cfg.AgentFullAccess=false;cfg.AgentSandboxEnabled=false;cfg.AgentTerminalPolicy=AgentTerminalPolicy.ConfirmEach;panel.RefreshState();Check(approval.SelectedIndex==0&&!panel.HasUnsavedChanges&&All<CheckBox>(panel).Single(c=>c.Name=="AgentSandboxEnabled").IsChecked==false,"restricted old settings display request approval without enabling the sandbox or becoming dirty");
            Check(panel.Save()&&cfg.AgentApprovalMode==AgentApprovalMode.Legacy&&!cfg.AgentSandboxEnabled&&!cfg.AgentFullAccess&&cfg.AgentTerminalPolicy==AgentTerminalPolicy.ConfirmEach,"saving untouched old settings does not widen permissions or remove terminal confirmation");
            var legacyAccess=All<ComboBox>(panel).Single(c=>c.Name=="AgentAccessMode");WithConfirmation(()=>legacyAccess.SelectedIndex=0,false);Check(legacyAccess.SelectedIndex==1&&approval.SelectedIndex==0&&!panel.HasUnsavedChanges&&!cfg.AgentFullAccess,"cancelling the old file-range control also preserves existing permissions");WithConfirmation(()=>legacyAccess.SelectedIndex=0,true);Check(panel.Save()&&cfg.AgentApprovalMode==AgentApprovalMode.Legacy&&cfg.AgentFullAccess&&cfg.AgentTerminalPolicy==AgentTerminalPolicy.ConfirmEach,"confirmed legacy file expansion retains its terminal confirmation policy");
            cfg.AgentFullAccess=true;panel.RefreshState();Check(approval.SelectedIndex==2&&!panel.HasUnsavedChanges,"old unrestricted file settings use the full-access display name without mutation");
            approval.SelectedIndex=0;Check(All<CheckBox>(panel).Single(c=>c.Name=="AgentSandboxEnabled").IsChecked==true,"explicit ask preset enables sandbox");
            Check(panel.Save()&&cfg.AgentApprovalMode==AgentApprovalMode.Ask&&cfg.AgentSandboxEnabled,"permission settings save");Check(new SettingsStore(Path.Combine(root,"settings.json")).Load().AgentSandboxEnabled,"sandbox preference survives disk persistence");Capture(owner,"settings-permissions");
            WithConfirmation(()=>approval.SelectedIndex=2,false);Check(approval.SelectedIndex==0&&!panel.HasUnsavedChanges&&cfg.AgentApprovalMode==AgentApprovalMode.Ask,"cancelling full access in settings restores the selection and leaves permissions unchanged");
            WithConfirmation(()=>approval.SelectedIndex=2,true);Check(panel.Save()&&cfg.AgentApprovalMode==AgentApprovalMode.Full&&!cfg.AgentSandboxEnabled,"confirmed full access saves without a duplicate prompt");approval.SelectedIndex=0;Check(panel.Save(),"settings can return to request approval");
            owner.Close();var work=pet.CreateDraftConversation(null,true);pet.PrepareConversationSubmission(work);pet.FinishConversationSubmission(work);var sibling=pet.CreateDraftConversation(null,true);var chat=new ChatWindow(pet,work);chat.Show();chat.UpdateLayout();Pump();
            // Full chat now opens with its sidebar visible; compact entry tests close it explicitly.
            if(!All<Button>(chat).Any(b=>b.Name=="CompactChatEntry"&&b.IsVisible)){Click(All<Button>(chat).Single(b=>b.Name=="ToggleAppSidebar"));Pump();}
            Check(All<Button>(chat).Any(b=>b.Name=="CompactChatEntry"&&b.IsVisible),"compact chat/work navigation is visible");Check(!All<Button>(chat).Any(b=>b.Name=="ConversationModePicker"),"old mode picker is removed");
            var input=All<MarkdownEditor>(chat).Single(t=>t.Name=="MessageInput");var composer=Field<ConversationComposer>(chat,"composer");Check(All<Button>(chat).Any(b=>b.Name=="AgentPermissionPicker"&&b.IsVisible),"work composer has change permissions control");
            Check(All<TextBlock>(chat).Any(t=>t.Name=="AiAccuracyNotice"&&t.Text==pet.Skin.Name+"是人工智能，有时会出错。请仔细核对回答。"),"composer accuracy notice names the current pet");
            var entry=All<ConversationEntryTabs>(chat).Single(t=>t.IsVisible);var labels=All<TextBlock>(entry).Where(t=>t.Text=="聊天"||t.Text=="工作").ToArray();Check(labels.Length==2&&Math.Abs(labels[0].TranslatePoint(new Point(0,labels[0].BaselineOffset),entry).Y-labels[1].TranslatePoint(new Point(0,labels[1].BaselineOffset),entry).Y)<0.5,"chat and work labels share the same rendered baseline");
            input.Text="工作草稿";string workId=chat.ConversationId;Click(All<Button>(chat).Single(b=>b.Name=="CompactChatEntry"));Check(!chat.WorkEntry&&input.Text==""&&chat.ConversationId!=workId,"chat entry has an independent draft");input.Text="聊天草稿";string personalId=chat.ConversationId;Check(!All<Button>(chat).Any(b=>b.Name=="AgentPermissionPicker"&&b.IsVisible),"chat does not expose tool permissions");
            Click(All<Button>(chat).Single(b=>b.Name=="CompactWorkEntry"));Check(chat.WorkEntry&&chat.ConversationId==workId&&input.Text=="工作草稿","work entry restores its draft and identity");
            Click(All<Button>(chat).Single(b=>b.Name=="CompactChatEntry"));Check(chat.ConversationId==personalId&&input.Text=="聊天草稿","chat entry restores its own draft");Click(All<Button>(chat).Single(b=>b.Name=="CompactWorkEntry"));
            var source=PresentationSource.FromVisual(input);var tab=new KeyEventArgs(Keyboard.PrimaryDevice,source,0,Key.Tab){RoutedEvent=Keyboard.PreviewKeyDownEvent};input.RaiseEvent(tab);Pump();Check(chat.WorkEntry&&chat.ConversationId==workId,"Tab never changes entry");
            input.Text="/";input.CaretIndex=1;Pump();var trigger=Field<Popup>(composer,"triggerPopup");Check(!All<TextBlock>(trigger.Child).Any(t=>t.Text=="工作模式"||t.Text=="对话模式"),"slash palette no longer switches mode");input.Clear();
            Check(composer.TryExecutePermissionCommand("/permissions auto")&&work.EffectiveSettings().AgentApprovalMode==AgentApprovalMode.Auto,"slash command switches this session to auto review");Check(sibling.EffectiveSettings().AgentApprovalMode==AgentApprovalMode.Ask,"session change does not affect sibling");var record=ProjectCatalogStore.AllConversations(pet.ProjectStore.Load()).Single(c=>c.Id==work.Id);Check(record.HasPermissionOverride&&record.ApprovalMode==AgentApprovalMode.Auto,"session override persists in catalog");
            var permission=All<Button>(chat).Single(b=>b.Name=="AgentPermissionPicker");Click(permission);var menu=permission.ContextMenu;Check(menu.IsOpen&&menu.Items.Count==4&&menu.Items.OfType<MenuItem>().Count(i=>i.Name=="PermissionAsk"||i.Name=="PermissionAuto"||i.Name=="PermissionFull")==3,"permission menu contains only its heading and three profiles");Check(!All<TextBlock>(menu).Any(t=>t.Text=="了解更多"||t.Text.Contains("沿用旧设置")),"permission menu has no fourth legacy profile or learn-more text");Check(All<System.Windows.Shapes.Path>(menu).Count(g=>g.Name.StartsWith("PermissionGlyph"))==3,"all three permission profiles have vector icons");Capture((FrameworkElement)menu,"permission-menu");menu.IsOpen=false;
            WithConfirmation(()=>composer.TryExecutePermissionCommand("/permissions full"),false,dialog=>{
                Check(Object.ReferenceEquals(dialog.Owner,chat)&&dialog.WindowStyle==WindowStyle.None,"full access prompt is styled and owned by the current chat");
                Check(All<TextBlock>(dialog).Any(t=>t.Text=="文件和文件夹")&&All<TextBlock>(dialog).Any(t=>t.Text=="终端命令")&&All<TextBlock>(dialog).Any(t=>t.Text=="互联网和已连接的应用")&&!All<TextBlock>(dialog).Any(t=>t.Text.Contains("了解更多")),"full access prompt explains three capability groups without a learn-more link");
                Check(All<Button>(dialog).Single(b=>b.Name=="CancelPermissionChange").IsDefault&&work.EffectiveSettings().AgentApprovalMode==AgentApprovalMode.Auto,"cancel is the safe keyboard default and permissions stay unchanged before confirmation");Capture(dialog,"full-access-confirmation");
            });Check(work.EffectiveSettings().AgentApprovalMode==AgentApprovalMode.Auto,"cancelled composer selection keeps automatic review");
            WithConfirmation(()=>composer.TryExecutePermissionCommand("/permissions full"),true);Check(work.EffectiveSettings().AgentApprovalMode==AgentApprovalMode.Full&&!work.EffectiveSettings().AgentSandboxEnabled,"confirmed composer selection activates full access");
            foreach(string mode in new[]{"full","ask","auto"}){
                if(mode!="full")composer.TryExecutePermissionCommand("/permissions "+mode);chat.UpdateLayout();Pump();var label=All<TextBlock>(permission).Single(t=>t.Name=="AgentPermissionLabel");var glyph=All<Border>(permission).Single(b=>b.Name=="ConversationModeGlyph");var centerText=label.TranslatePoint(new Point(0,label.ActualHeight/2),permission).Y;var centerIcon=glyph.TranslatePoint(new Point(0,glyph.ActualHeight/2),permission).Y;
                Check(label.FontSize==13&&glyph.ActualWidth==16&&Math.Abs(centerText-centerIcon)<0.5&&permission.ActualHeight==32,"permission icon and text share consistent size and vertical alignment: "+mode);Check(((SolidColorBrush)permission.Background).Color.A==0,"permission control uses the transparent composer surface: "+mode);Capture(permission,"permission-"+mode);
            }
            var confirm=new PermissionChangeDialog("测试权限更改","仅测试确认界面，不执行任何操作。"){Owner=chat};confirm.Dispatcher.BeginInvoke(new Action(delegate{Click(All<Button>(confirm).Single(b=>b.Name=="CancelPermissionChange"));}));confirm.ShowDialog();Check(!confirm.IsVisible,"permission increase dialog can cancel");
            chat.Width=1280;chat.Height=850;chat.UpdateLayout();Pump();if(!All<Button>(chat).Any(b=>b.Name=="WorkEntry"&&b.IsVisible)){Click(All<Button>(chat).Single(b=>b.Name=="ToggleAppSidebar"));Pump();}Check(All<Button>(chat).Any(b=>b.Name=="WorkEntry"&&b.IsVisible)&&!All<Button>(chat).Any(b=>b.Name=="CompactWorkEntry"&&b.IsVisible),"wide window shows the sidebar entry control");Capture(chat,"work-entry-wide");
            Click(All<Button>(chat).Single(b=>b.Name=="ChatEntry"));Check(!All<Button>(chat).Any(b=>b.Name=="NewProject"&&b.IsVisible),"personal chat sidebar hides projects");Capture(chat,"chat-entry-wide");chat.Width=700;chat.UpdateLayout();Pump();Capture(chat,"chat-entry-compact");cfg.AgentEnabled=true;pet.ShowQuickChat();Pump();var quick=app.Windows.OfType<QuickChatWindow>().Single();quick.UpdateLayout();Check(!All<ConversationEntryTabs>(quick).Any()&&!pet.ConversationSettings(Field<ConversationSession>(quick,"session")).AgentEnabled,"quick chat stays personal even when global work is enabled and has no entry switch");Check(!All<TextBlock>(quick).Any(t=>t.Name=="AiAccuracyNotice"),"quick chat omits the accuracy notice and keeps room for status");Capture(quick,"quick-chat-compact");quick.Close();chat.Close();Console.WriteLine("Permission and entry UI smoke: "+checks+" passed");return 0;
        }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{foreach(var w in app.Windows.OfType<Window>().ToArray())w.Close();if(pet!=null)pet.Close();app.Shutdown();}}
    }
}
